set-variable.value:
@{
      var jwt = (Jwt)context.Variables["jwt"];
      if (jwt.Claims.ContainsKey("upn")) { return jwt.Claims["upn"].FirstOrDefault(); }
      if (jwt.Claims.ContainsKey("preferred_username")) { return jwt.Claims["preferred_username"].FirstOrDefault(); }
      return "";
  }

@{
      var jwt = (Jwt)context.Variables["jwt"];
      if (jwt.Claims.ContainsKey("groups")) {
          return jwt.Claims["groups"].Contains("{{aeg-audience-group-id}}");
      }
      // Groups overage (caller in 200+ groups) omits the claim. The security
      // gate fails CLOSED here; enable a managed-identity Graph checkMemberGroups
      // fallback for large-group tenants (see docs/apim-gateway-setup.md).
      return false;
  }

send-request.set-url:
@{
        var resource = "{{aeg-dataverse-resource}}";
        // M-3: OData-escape the agent id (double any single quote) before it is
        // concatenated into the $filter, so a value containing a quote cannot
        // alter the query.
        var agentId = ((string)context.Variables["agentId"]).Replace("'", "''");
        return resource + "/api/data/v9.2/fsi_caicompliancestates?$select=fsi_risklevel&$filter=fsi_agentid eq '" + agentId + "'";
    }

set-variable.value:
@{
      try {
          var resp = (IResponse)context.Variables["govResp"];
          if (resp == null || resp.StatusCode != 200) { return false; }
          var rows = resp.Body.As<JObject>(true)["value"] as JArray;
          if (rows == null || rows.Count == 0) { return false; }
          var risk = (string)rows[0]["fsi_risklevel@OData.Community.Display.V1.FormattedValue"];
          return !(risk == "High" || risk == "Critical");
      } catch (Exception) { return false; }
  }

send-request.set-url:
@{
        var resource = "{{aeg-dataverse-resource}}";
        // M-3: OData-escape both the agent id and the caller UPN (double any
        // single quote) before concatenating into the $filter.
        // H-4: also select fsi_ttlexpiresat so the cache TTL can be honored below.
        var agentId = ((string)context.Variables["agentId"]).Replace("'", "''");
        var upn = ((string)context.Variables["callerUpn"]).Replace("'", "''");
        return resource + "/api/data/v9.2/fsi_cbgentitlementmaterializeds?$select=fsi_decision,fsi_pathway,fsi_decisionreason,fsi_ttlexpiresat&$filter=fsi_agentid eq '" + agentId + "' and fsi_userupn eq '" + upn + "'";
    }

set-variable.value:
@{
      try {
          var resp = (IResponse)context.Variables["entResp"];
          if (resp == null || resp.StatusCode != 200) { return new JObject(); }
          var rows = resp.Body.As<JObject>(true)["value"] as JArray;
          if (rows == null || rows.Count == 0) { return new JObject(); }
          var row = (JObject)rows[0];
          // H-4: honor the cache TTL. An expired materialized decision is treated
          // as no row at all, so the contract falls through to unmapped => allow +
          // anomaly rather than acting on a stale decision. hasEntRow, pathway,
          // materializedAllow and anomaly below all derive from this row, so they
          // follow suit. fsi_ttlexpiresat is the raw UTC (ISO-8601) value; a value
          // that cannot be parsed is left in force (TTL simply not enforced).
          var ttl = (string)row["fsi_ttlexpiresat"];
          if (!string.IsNullOrEmpty(ttl)) {
              DateTimeOffset expiresAt;
              if (DateTimeOffset.TryParse(ttl, out expiresAt) && expiresAt.UtcDateTime < DateTime.UtcNow) {
                  return new JObject();
              }
          }
          return row;
      } catch (Exception) { return new JObject(); }
  }

@{
      var audienceOk = (bool)context.Variables["isAudienceMember"];
      var compliant = (bool)context.Variables["agentCompliant"];
      var hasRow = (bool)context.Variables["hasEntRow"];
      var allow = (bool)context.Variables["materializedAllow"];
      var reason = (string)context.Variables["materializedReason"];
      if (audienceOk == false) { return "OutOfPolicyAudience"; }
      if (compliant == false) { return "AgentNonCompliant"; }
      if (hasRow == false) { return "None"; }
      if (allow == false) { return reason; }
      return "None";
  }

@{
      var pathway = (string)context.Variables["pathway"];
      var knownPathway = new [] { "none", "mcp-cs", "mcp-agentbuilder", "api-direct", "metered" }.Contains(pathway);
      var decisionLabel = (string)((JObject)context.Variables["entRow"])["fsi_decision@OData.Community.Display.V1.FormattedValue"];
      return knownPathway == false || decisionLabel == "Fail-open - Anomaly";
  }

fragment.log-to-eventhub:
@{
      return new JObject(
          new JProperty("schemaVersion", "1.0"),
          new JProperty("correlationId", (string)context.Variables["correlationId"]),
          new JProperty("decisionTime", DateTime.UtcNow.ToString("o")),
          new JProperty("agentId", (string)context.Variables["agentId"]),
          new JProperty("userObjectId", (string)context.Variables["callerOid"]),
          new JProperty("channel", "{{aeg-channel}}"),
          new JProperty("pathway", (string)context.Variables["pathway"]),
          new JProperty("decision", (string)context.Variables["decision"]),
          new JProperty("denyReason", (string)context.Variables["denyReason"]),
          new JProperty("anomaly", (bool)context.Variables["anomaly"]),
          new JProperty("httpStatus", ((string)context.Variables["decision"]) == "Deny" ? 403 : 200),
          new JProperty("policyVersion", "{{aeg-policy-version}}")
      ).ToString(Newtonsoft.Json.Formatting.None);
  }

return-response.set-body:
@{
            return new JObject(
                new JProperty("error", "access_denied"),
                new JProperty("message", "Your request was not authorized by the agent eligibility gateway. If you believe this is in error, contact your administrator and provide the correlation ID below."),
                new JProperty("denyReason", (string)context.Variables["denyReason"]),
                new JProperty("correlationId", (string)context.Variables["correlationId"])
            ).ToString();
        }
